    """Commandes existantes : le compte est celui de l'entreprise. Mise en avant d'offre ajoutée ; boosts candidats retirés."""
    PublicationOrder = apps.get_model('Emploi', 'PublicationOrder')
    for order in PublicationOrder.objects.filter(user__isnull=True, employer__isnull=False).select_related('employer'):
        order.user_id = order.employer.user_id
        order.save(update_fields=['user'])
    ServicePlan = apps.get_model('Emploi', 'ServicePlan')
    ServicePlan.objects.get_or_create(code='offre-mise-en-avant', defaults=dict(
        kind='job_boost', name="Mise en avant d'une offre d'emploi",
        description="Votre offre épinglée en haut de la liste pendant 14 jours, avec le badge « À la une ».",
        price=2000, duration_days=14, order=6, is_active=True))
    # Le boost de profil / de candidature est retiré : les candidats ne paient jamais pour être visibles.
    ServicePlan.objects.filter(kind__in=('cand_boost', 'cand_app')).update(is_active=False)


